        { name: "South Dakota", rings: [[{a:80,r:0}, {a:86,r:0}, {a:66,r:0}, {a:207,r:0}, {a:253,r:1}, {a:136,r:1}]] },
        { name: "Texas", rings: [[{a:278,r:1}], [{a:5,r:0}, {a:64,r:0}, {a:279,r:1}, {a:84,r:0}, {a:89,r:0}]] }
