    // Reconstructs each state's full boundary rings from the shared arcs
    // above (dropping the duplicate junction point at each arc join), once
    // at load, into a flat point-array format for drawing each frame.
    function buildStatePolygons() {
        return STATE_BOUNDARIES.map(state => {
            const polyRings = state.rings.map(refs => {
                const pts = [];
                refs.forEach((ref, i) => {
                    const arc = STATE_BORDER_ARCS[ref.a];
                    const seg = ref.r ? [...arc].slice().reverse() : arc;
                    const startAt = i === 0 ? 0 : 1; // drop dup junction point
                    for (let k = startAt; k < seg.length; k++) {
                        pts.push({ lat: seg[k][0], lon: seg[k][1] });
                    }
                });
                // drop the trailing duplicate that closes the ring back to its
                // own start point — ctx.closePath() handles that at draw time,
                // matching the open-ring convention used elsewhere in this file
                if (pts.length > 1 && pts[0].lat === pts[pts.length - 1].lat &&
                    pts[0].lon === pts[pts.length - 1].lon) {
                    pts.pop();
                }
                return pts;
            });
            return { name: state.name, rings: polyRings };
        });
    }
    const STATE_POLYGONS = buildStatePolygons();

